// Extrai dados essenciais do payload da Evolution API v1 / v2
const body = $input.first().json.body || $input.first().json;

// Se for evento MESSAGES_UPSERT da Evolution API
const data = body.data || body;
const key = data.key || {};

// 1. Ignora mensagens enviadas pelo próprio chip (fromMe: true)
if (key.fromMe === true) {
  return [];
}

// 2. Extrai o número do remetente
const remoteJid = key.remoteJid || '';
if (!remoteJid || remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast')) {
  // Ignora grupos e status do WhatsApp
  return [];
}

const cleanPhone = remoteJid.replace(/\D/g, '');

// 3. Extrai o texto da mensagem
const message = data.message || {};
const text = message.conversation ||
  message.extendedTextMessage?.text ||
  message.imageMessage?.caption ||
  '';

if (!text || text.trim().length === 0) {
  return [];
}

const pushName = data.pushName || 'Parceiro';
const primeiroNome = pushName.split(' ')[0] || 'Parceiro';

return [{
  json: {
    remoteJid,
    cleanPhone,
    pushName,
    primeiroNome,
    textoRecebido: text.trim(),
    instanceName: body.instance || 'meutim',
    timestamp: new Date().toISOString()
  }
}];

// Classificador de Intenção do Super Agente Vendedor - Hotel no Zap
const item = $input.first().json;
const texto = (item.textoRecebido || '').toLowerCase();
const primeiroNome = item.primeiroNome || 'Parceiro';

const LINK_CADASTRO = 'https://lp.hotelnozap.com.br';
const ADMIN_WHATSAPP = '5565996173004'; // Sr. Everaldo Souza

let intencao = 'GERAL';
let resposta = '';
let acionarFechamento = false;
let acionarAlertaVip = false;
let descartar = false;

// Regra 1: Quem fala / Do que se trata?
if (
  texto.includes('quem fala') ||
  texto.includes('quem é') ||
  texto.includes('de onde é') ||
  texto.includes('do que se trata') ||
  texto.includes('qual o assunto') ||
  texto.includes('quem tá falando') ||
  texto.includes('quem esta falando')
) {
  intencao = 'QUEM_FALA';
  resposta = 'Oi! Aqui é o *Everaldo Souza*, fundador do *Hotel no Zap* aqui de MT. Encontrei o hotel de vocês no Google e entrei em contato direto porque criamos a Plataforma de Gestão de Hotéis com Inteligência Artificial especializada para hotéis e pousadas atenderem hóspedes no WhatsApp.';
}
// Regra 2: Fechamento / Preço / Demonstração / Como pago / Pode ligar?
else if (
  texto.includes('preço') ||
  texto.includes('preco') ||
  texto.includes('valor') ||
  texto.includes('quanto custa') ||
  texto.includes('plano') ||
  texto.includes('pode me ligar') ||
  texto.includes('me liga') ||
  texto.includes('como pago') ||
  texto.includes('como funciona') ||
  texto.includes('quero testar') ||
  texto.includes('quero conhecer') ||
  texto.includes('como cadastro') ||
  texto.includes('link')
) {
  intencao = 'FECHAMENTO';
  acionarFechamento = true;
  acionarAlertaVip = true;
  resposta = `Maravilha! Você pode fazer a ativação imediata do seu hotel por este link inteiramente grátis:\n🔗 ${LINK_CADASTRO}\n\nLeva menos de 2 minutos para preencher. Vou ficar te aguardando por aqui!`;
}
// Regra 3: Objeção de Sistema Atual
else if (
  texto.includes('já temos sistema') ||
  texto.includes('ja temos sistema') ||
  texto.includes('já uso') ||
  texto.includes('ja uso') ||
  texto.includes('tenho pms') ||
  texto.includes('hsystem') ||
  texto.includes('totvs') ||
  texto.includes('desbravador') ||
  texto.includes('foco') ||
  texto.includes('silbeck')
) {
  intencao = 'OBJECAO_SISTEMA';
  resposta = 'Que excelente! O Hotel no Zap não precisa substituir o sistema de vocês caso não queiram. Nossa tecnologia atua como o Vendedor e Recepcionista com Inteligência Artificial no WhatsApp do hotel para responder na hora e fechar reservas diretas sem pagar comissão para Booking ou Airbnb.';
}
// Regra 4: É robô?
else if (
  texto.includes('é robô') ||
  texto.includes('e robo') ||
  texto.includes('é ia') ||
  texto.includes('inteligencia artificial') ||
  texto.includes('mensagem automatica')
) {
  intencao = 'OBJECAO_ROBO';
  resposta = 'Sou a Inteligência Artificial desenvolvida pelo Everaldo aqui no Hotel no Zap! Nosso objetivo é libertar a sua recepção das mensagens repetitivas de cotação e fotos no WhatsApp, atendendo os hóspedes em menos de 3 segundos.';
}
// Regra 5: Descarte / Sem interesse
else if (
  texto.includes('não tenho interesse') ||
  texto.includes('nao tenho interesse') ||
  texto.includes('não quero') ||
  texto.includes('nao quero') ||
  texto.includes('pare de enviar') ||
  texto.includes('remover') ||
  texto.includes('sai fora')
) {
  intencao = 'DESCARTE';
  descartar = true;
  resposta = 'Entendido perfeitamente! Já registrei aqui e não te enviaremos mais mensagens. Um abraço e ótimas reservas!';
}
// Regra 6: Positivo / Apresentação Geral
else {
  intencao = 'GERAL';
  resposta = `Olá! Tudo bem, ${primeiroNome}? Me chamo Everaldo, sou fundador do Hotel no Zap aqui no MT. Vocês perdem muito tempo na recepção respondendo dúvidas e fechando reservas no WhatsApp? Desenvolvemos uma IA que atende em segundos e fecha reservas diretas sem comissão!`;
}

// Mensagem de follow-up que será disparada 5 minutos após o link
const mensagemFollowup5Min = `${primeiroNome}, deu tudo certo com o preenchimento do cadastro pelo link? Se tiver qualquer dúvida estou por aqui para te ajudar a finalizar!`;

// Mensagem de alerta para o Everaldo
const mensagemAlertaEveraldo = `🚨 *NOVO CLIENTE EM FECHAMENTO - HOTEL NO ZAP!*\n\n📱 *Lead:* ${item.pushName} (${item.cleanPhone})\n💬 *Disse:* "${item.textoRecebido}"\n🎯 *Ação:* Link da LP enviado e follow-up de 5 minutos iniciado!\n\n👉 *Clique para falar com ele no WhatsApp:*\nhttps://wa.me/${item.cleanPhone}`;

return [{
  json: {
    ...item,
    intencao,
    resposta,
    acionarFechamento,
    acionarAlertaVip,
    descartar,
    mensagemFollowup5Min,
    mensagemAlertaEveraldo,
    adminWhatsapp: ADMIN_WHATSAPP
  }
}];
